import type { LucideIcon } from "lucide-react";
import { ArrowDownRight, ArrowUpRight } from "lucide-react";
import type { ComponentProps } from "react";
import { cn } from "@/lib/cn";

type StatCardProps = {
  label: string;
  value?: string;
  delta?: number;
  icon?: LucideIcon;
  loading?: boolean;
};

export function StatCard({ label, value, delta, icon: Icon, loading = false }: StatCardProps) {
  const hasValue = typeof value === "string" && value.length > 0;
  const positive = typeof delta === "number" && delta >= 0;
  const DeltaIcon = positive ? ArrowUpRight : ArrowDownRight;

  return (
    <section
      className="rounded-card border border-border bg-surface p-5 shadow-card"
      aria-busy={loading || undefined}
    >
      <div className="flex items-start justify-between gap-4">
        <div className="min-w-0">
          <p className="truncate text-sm text-muted">{label}</p>
          {loading ? (
            <div className="mt-2 h-8 w-24 animate-pulse rounded-md bg-canvas motion-reduce:animate-none" aria-hidden="true" />
          ) : hasValue ? (
            <p className="mt-1 text-2xl font-semibold tracking-tight">{value}</p>
          ) : (
            <p className="mt-1 text-sm text-muted">No data yet</p>
          )}
        </div>
        {Icon ? <Icon className="size-5 shrink-0 text-muted" aria-hidden="true" /> : null}
      </div>
      {typeof delta === "number" && !loading ? (
        <p className={cn("mt-3 inline-flex items-center gap-1 text-sm", positive ? "text-success" : "text-danger")}>
          <DeltaIcon className="size-4" aria-hidden="true" />
          <span>{Math.abs(delta)}%</span>
          <span className="text-muted">vs last month</span>
        </p>
      ) : null}
    </section>
  );
}
```

The delta is visual, so the arrow is `aria-hidden`; the text `+12% vs last month` is already readable. Add a Vitest test that queries by label and asserts the percent text.

```tsx
import { useQuery } from "@tanstack/react-query";
import { useSearchParams } from "react-router";
import { ordersQuery } from "@/features/orders/api";
import { OrderStatusBadge } from "@/features/orders/components/OrderStatusBadge";
import { EmptyOrders } from "@/features/orders/components/EmptyOrders";
import { ErrorState } from "@/components/patterns/ErrorState";
import { TableSkeleton } from "@/components/patterns/TableSkeleton";
import { formatMoney } from "@/lib/format";

const statuses = ["all", "paid", "pending", "refunded"] as const;

export function OrdersPage() {
  const [params, setParams] = useSearchParams();
  const status = params.get("status") ?? "all";
  const { data, isPending, isError, refetch } = useQuery(ordersQuery.list());

  if (isPending) return <TableSkeleton rows={6} />;
  if (isError) return <ErrorState onRetry={refetch} />;

  const filtered = status === "all" ? data : data.filter((order) => order.status === status);

  return (
    <section className="space-y-4">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <h1 className="text-2xl font-semibold tracking-tight">Orders</h1>
        <label className="flex items-center gap-2 text-sm text-muted">
          Status
          <select
            className="h-10 rounded-lg border border-border bg-surface px-3 text-ink focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-brand"
            value={status}
            onChange={(event) => {
              const next = new URLSearchParams(params);
              if (event.target.value === "all") next.delete("status");
              else next.set("status", event.target.value);
              setParams(next);
            }}
          >
            {statuses.map((value) => <option key={value} value={value}>{value}</option>)}
          </select>
        </label>
      </div>

      {filtered.length === 0 ? (
        <EmptyOrders />
      ) : (
        <div className="overflow-x-auto rounded-card border border-border bg-surface">
          <table className="w-full text-left text-sm">
            <caption className="sr-only">Orders, filtered by status</caption>
            <thead className="border-b border-border text-muted">
              <tr>
                <th scope="col" className="px-4 py-3 font-medium">Customer</th>
                <th scope="col" className="px-4 py-3 font-medium">Status</th>
                <th scope="col" className="px-4 py-3 text-right font-medium">Total</th>
              </tr>
            </thead>
            <tbody>
              {filtered.map((order) => (
                <tr key={order.id} className="border-t border-border last:border-0">
                  <td className="px-4 py-3">{order.customer}</td>
                  <td className="px-4 py-3"><OrderStatusBadge status={order.status} /></td>
                  <td className="px-4 py-3 text-right tabular-nums">{formatMoney(order.totalCents)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </section>
  );
}
```

